-- Replace the Uganda villages with the updated list (villages.csv, Nov 2026),
-- which adds the nine new sites (024, 034, 049, 052-055, 058, 063) so their
-- enrollees show village names instead of "Village <code>". Existing sites are
-- unchanged apart from 15 Bumanya-parish villages (Kaliro) now listed under
-- Bumanya HCIV (055) instead of Nawaikoke HCIII (056). Duplicate village codes
-- at Lira-Kato were fixed in the sheet before loading (AKURINGOTOO 16,
-- KAMRONO 19, LARWEE 20). The table has no primary key, so this swaps all UG
-- rows rather than upserting; one statement, so it's atomic. Burkina Faso
-- (countryid = 2) is untouched (the sheet's BF rows match what's loaded).

with removed as (
  delete from public.villages where countryid = 1
)
insert into public.villages
  (countryid, country, districtid, district, subcountyid, subcounty, parishid, parish, villageid, village, mrcid, mrc)
